('1bf0f1a6-fb1d-59ad-ba02-93dd946c75c1', '2fb8b926-5747-545d-9af6-82cb4940584c', 'mcq', 'single', 'en', '$(2a - 3)^2 = ?$', '{"options":["$4a^2 - 9$","$4a^2 - 6a + 9$","$4a^2 - 12a + 9$","$2a^2 - 12a + 9$"]}'::jsonb, '{"index":2}'::jsonb, '$(2a)^2 = 4a^2$, middle term $-2 \cdot 2a \cdot 3 = -12a$, last term $9$.', null, 'original', null, null, 2, array['square-difference']::text[], true),
