('1fafdf9a-1b52-56ec-ad49-36c9cc6b523a', '2fb8b926-5747-545d-9af6-82cb4940584c', 'mcq', 'single', 'en', 'If $a - b = 3$ and $ab = 4$, what is $(a + b)^2$?', '{"options":["$13$","$7$","$1$","$25$"]}'::jsonb, '{"index":3}'::jsonb, '$(a + b)^2 = (a - b)^2 + 4ab = 9 + 16 = 25$.', null, 'original', null, null, 3, array['sum-product']::text[], true),
('9aab3bca-1d3d-5ee6-a410-45ad9d5b2a68', '2fb8b926-5747-545d-9af6-82cb4940584c', 'mcq', 'single', 'en', 'Which is the factorisation of $x^2 - 9$?', '{"options":["$(x - 3)^2$","$(x + 3)(x - 3)$","$(x + 9)(x - 1)$","$(x + 3)^2$"]}'::jsonb, '{"index":1}'::jsonb, '$a^2 - b^2 = (a + b)(a - b)$ with $b = 3$.', null, 'original', null, null, 1, array['factorise','difference-of-squares']::text[], true),
